using System.IO;
using System.Text.Json;
using Orbit.Core;
namespace OrbitLauncher;
public partial class MainWindow {
 async Task CheckLoaderInstallAsync(string root){var report=new List<string>();string original=settings.GameRoot;async Task<JsonElement> Js(string code)=>JsonDocument.Parse(await brawlBrowser!.CoreWebView2.ExecuteScriptAsync(code)).RootElement.Clone();
 try{string fixtureConfig=Path.Combine(root,"fixture-path.txt");string fixture=File.Exists(fixtureConfig)?File.ReadAllText(fixtureConfig).Trim():Path.Combine(root,"game");Directory.CreateDirectory(fixture);string folder=Path.Combine(fixture,"versions","1.21.1");Directory.CreateDirectory(folder);foreach(string ext in new[]{".json",".jar"}){string target=Path.Combine(folder,"1.21.1"+ext);if(!File.Exists(target))File.Copy(Path.Combine(original,"versions","1.21.1","1.21.1"+ext),target);}byte[] originalMetadata=File.ReadAllBytes(Path.Combine(folder,"1.21.1.json"));string profiles=Path.Combine(fixture,"launcher_profiles.json");string originalProfiles=File.Exists(profiles)?File.ReadAllText(profiles):"";settings.GameRoot=fixture;RootBox.Text=fixture;NicknameBox.Text="ProbePlayer";settings.Theme="brawl stars";ApplyTheme();await RefreshVersions();Navigate("Home");await brawlInitTask;await brawlPageReady.Task.WaitAsync(TimeSpan.FromSeconds(35));SyncBrawlState();await Task.Delay(1000);
 foreach(string loader in new[]{"Fabric","Forge"}){await Js("document.querySelector('.lobby-mode').click()");await Task.Delay(300);await Js("document.querySelector('.orbit-quick-actions ."+loader.ToLowerInvariant()+"').click()");await Task.Delay(300);for(int i=0;i<1000&&quickCatalogLoading;i++)await Task.Delay(100);await Task.Delay(300);if(quickCatalogError.Length>0)throw new Exception(quickCatalogError);await Js("(()=>{const s=document.querySelector('[aria-label=\"Quick loader\"] select');Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(s,'1.21.1');s.dispatchEvent(new Event('change',{bubbles:true}));})()");await Task.Delay(250);await Js("document.querySelector('[aria-label=\"Quick loader\"] button.primary').click()");await Task.Delay(250);for(int i=0;i<12000&&quickLoaderCts!=null;i++)await Task.Delay(100);FlushLog();report.Add(loader+" STATUS: "+StatusText.Text);report.Add(LogBox.Text);File.WriteAllLines(Path.Combine(root,"install-checks.txt"),report);if(quickLoaderCts!=null)throw new TimeoutException("UI installation timed out");var installed=Versions.Scan(fixture).FirstOrDefault(v=>v.Loader==loader&&v.BaseVersion=="1.21.1")??throw new Exception(loader+" failed through the real install button: "+StatusText.Text);var plan=LaunchEngine.Build(new LauncherSettings{GameRoot=fixture,Nickname="ProbePlayer",Isolated=false},installed.Id);if(plan.Missing.Count>0||LaunchEngine.CheckAssets(new LauncherSettings{GameRoot=fixture},plan).Count>0)throw new Exception(loader+" installation is incomplete: "+string.Join(";",plan.Missing));if(!File.ReadAllBytes(Path.Combine(folder,"1.21.1.json")).SequenceEqual(originalMetadata))throw new Exception("Existing vanilla metadata was changed");if(originalProfiles.Length>0&&File.ReadAllText(profiles)!=originalProfiles)throw new Exception("Existing launcher profiles were changed");if(game!=null)throw new Exception("Minecraft must not start during installer check");report.Add("PASS "+loader+" full install through real UI, client/libraries/assets/Java verified; original metadata and launcher profiles preserved; no game launched");using(var image=File.Create(Path.Combine(root,loader.ToLowerInvariant()+"-install.png")))await brawlBrowser!.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,image);}
 }finally{settings.GameRoot=original;File.WriteAllLines(Path.Combine(root,"install-checks.txt"),report);}
 }
